"""Same six source units/observations as the one rejected model task; review only."""
import datetime,hashlib,json,re
from pathlib import Path
P=Path(__file__).resolve().parent;request=json.loads((P/'queue-model-faq-v1/request.json').read_text());packet=json.loads(request['messages'][1]['content']);protocol=json.loads((P/'queue-model-faq-v1/protocol.json').read_text())
rows=[
('clear-contract','What does `clearQueue` establish about pending callers and active work?','O que `clearQueue` estabelece sobre chamadores pendentes e trabalho ativo?','Here, `clearQueue` removes queued callbacks without cancelling the active task. In the owned observations, cleared callbacks did not run and their caller Promises were still unsettled after 12 microtask checkpoints. This bounded result is not a universal liveness guarantee.','Neste recorte, `clearQueue` remove callbacks da fila sem cancelar a tarefa ativa. Nas observações próprias, os callbacks descartados não executaram e seus Promises de chamador continuaram sem resolução após 12 checkpoints de microtarefas. Esse resultado limitado não constitui uma garantia universal de vivacidade.',['limit:factory','limit:types:LimitFunction','queue:Queue'],['clear-before-start','clear-while-active']),
('caller-rejection','Does the empty catch in `run` make a failed caller Promise succeed?','O catch vazio em `run` torna bem-sucedido um Promise de chamador que falhou?','The empty catch in `run` handles its internal wait, after the result Promise has already been given to the caller resolver. In the owned observation, the caller rejected with the exact original failure object, while the next queued task fulfilled.','O catch vazio em `run` trata sua espera interna depois que o Promise de resultado já foi passado ao resolvedor do chamador. Na observação própria, o chamador foi rejeitado com o objeto exato da falha original, enquanto a tarefa seguinte na fila se completou.',['limit:factory'],['throw-preserves-identity']),
('deferred-start','Do `activeCount` and `pendingCount` show immediate callback execution?','`activeCount` e `pendingCount` mostram execução imediata do callback?','In the owned observation with two calls and concurrency one, the immediate counters were `activeCount=0` and `pendingCount=2`, with neither callback started. After one microtask checkpoint, they were `activeCount=1` and `pendingCount=1`, and only the first callback had begun. This observes scheduling, without measuring elapsed time.','Na observação própria com duas chamadas e concorrência um, os contadores imediatos eram `activeCount=0` e `pendingCount=2`, sem callback iniciado. Após um checkpoint de microtarefa, eram `activeCount=1` e `pendingCount=1`, e apenas o primeiro callback havia começado. Isso observa o escalonamento, sem medir o tempo decorrido.',['limit:factory','queue:Queue'],['deferred-start']),
('factory-return','Does `pLimit` return the task Promise or a limiter function?','`pLimit` retorna o Promise da tarefa ou uma função limitadora?','The outer `pLimit` call returns a limiter function, described by `LimitFunction`. Calling that returned function with a task returns `Promise<ReturnType>`. The selected implementation enqueues the callback inside a Promise constructor; these are two different API calls, so their return contracts must stay separate.','A chamada externa de `pLimit` retorna uma função limitadora, descrita por `LimitFunction`. Chamar essa função retornada com uma tarefa retorna `Promise<ReturnType>`. A implementação selecionada coloca o callback na fila dentro de um construtor de Promise; são duas chamadas distintas da API, com contratos separados de retorno.',['limit:factory','limit:types:pLimit','limit:types:LimitFunction'],[]),
('infinity-validation','Is `Number.POSITIVE_INFINITY` rejected by the selected concurrency guard?','`Number.POSITIVE_INFINITY` é rejeitado pela condição selecionada de concorrência?','The selected guard accepts positive integers or `Number.POSITIVE_INFINITY`, with `concurrency > 0`. In the supplied owned Infinity case, the limiter returned a function and fulfilled its task. That one result does not establish memory safety, a resource bound, a throughput guarantee or rate limiting.','A condição selecionada aceita inteiros positivos ou `Number.POSITIVE_INFINITY`, com `concurrency > 0`. No caso próprio fornecido de Infinity, o limitador retornou uma função e completou sua tarefa. Esse único resultado não estabelece segurança de memória, limite de recursos, garantia de vazão nem limitação de taxa.',['limit:factory'],['infinity']),
('undefined-queue','Does `dequeue` returning `undefined` prove that `Queue` was empty?','`dequeue` retornar `undefined` prova que `Queue` estava vazia?','The selected `Queue` can store `undefined`, and `dequeue` also returns `undefined` when no head exists. In the owned FIFO observation, size changes distinguished the stored value from the later empty return. The return value alone therefore does not prove that the queue was empty.','A `Queue` selecionada pode armazenar `undefined`, e `dequeue` também retorna `undefined` quando não existe cabeça. Na observação FIFO própria, as mudanças no tamanho distinguiram o valor armazenado do retorno vazio posterior. Portanto, apenas o valor retornado não prova que a fila estava vazia.',['queue:Queue','queue:types:Queue'],['queue-fifo-iteration'])]
faq=[];ledger_rows=[];word_counts={}
for key,en_q,pt_q,en_a,pt_a,evidence,observations in rows:
 assert key in protocol['requested_ids']and set(evidence)<=set(packet['source_evidence'])and set(observations)<={r['id']for r in packet['owned_runtime_observations']}
 assert re.findall(r'`([^`]+)`',en_q+'\n'+en_a)==re.findall(r'`([^`]+)`',pt_q+'\n'+pt_a)
 counts={'en':len(en_a.split()),'pt-br':len(pt_a.split())};word_counts[key]=counts;assert all(35<=n<=55 for n in counts.values()),(key,counts)
 faq.append({'id':key,'en':{'question':en_q,'answer':en_a},'pt-br':{'question':pt_q,'answer':pt_a},'evidence_ids':evidence})
 ledger_rows.append({'id':key,'en_q':en_q,'pt-br_q':pt_q,'en_a':en_a,'pt-br_a':pt_a,'evidence':evidence,'runtime_case_ids':observations})
assert {r['id']for r in faq}==set(protocol['requested_ids'])
output={'faq':faq}
with(P/'queue-deterministic-faq-v1.json').open('x')as f:f.write(json.dumps(output,indent=2,ensure_ascii=False)+'\n')
record={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'faq':ledger_rows,'units':packet['source_evidence'],'source_family':'sindresorhus/p-limit+direct-dependency:yocto-queue','facts_preceded_model_request':'The nine correction targets were preserved in sealedV3before the model request; this exact six-question assembly and wording were authored after seeing the rejected output.','same_prompt_source_units_and_runtime_cases_only':True,'word_counts':word_counts,'schema_shape_matches_model_task':True,'current_candidate_file':'queue-deterministic-faq-v1.json','current_candidate_sha256':hashlib.sha256((P/'queue-deterministic-faq-v1.json').read_bytes()).hexdigest(),'model_review':'queue-model-faq-v1/review.json','review_status':'CODEX_SOURCE_AND_BOUNDED_OBSERVATION_REVIEWED_NOT_INDEPENDENT_HUMAN_CERTIFICATION','owner_approved':False,'training_gold':False,'training_exclusion':True,'published':False,'model_calls':0,'comparison_limits':'Manual deterministic assembly versus one schema-constrained model call; no equal effort, causal neural gain, blind grading or independent accuracy claim.','full_semantic_equivalence_certified':False}
with(P/'queue-faq-ledger-v1.json').open('x')as f:f.write(json.dumps(record,indent=2,ensure_ascii=False)+'\n')
print({'pairs':len(faq),'word_counts':word_counts,'paired_inline_code_equal':True,'training_gold':0})
